-- Stock data from Tushare
CREATE DATABASE IF NOT EXISTS stock_data DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE stock_data;

DROP TABLE IF EXISTS daily_kline;
CREATE TABLE daily_kline (
  `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
  `ts_code` VARCHAR(20),
  `trade_date` VARCHAR(12),
  `open` DECIMAL(12,4),
  `high` DECIMAL(12,4),
  `low` DECIMAL(12,4),
  `close` DECIMAL(12,4),
  `pre_close` DECIMAL(12,4),
  `change` DECIMAL(12,4),
  `pct_chg` DECIMAL(10,4),
  `vol` DECIMAL(18,4),
  `amount` DECIMAL(18,4),
  `stock_name` VARCHAR(50),
  UNIQUE KEY `uk_ts_trade` (`ts_code`, `trade_date`),
  INDEX `idx_trade_date` (`trade_date`),
  INDEX `idx_ts_code` (`ts_code`),
  INDEX `idx_stock_name` (`stock_name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;












